body.script:
// Generate contribution graph
const weeksContainer = document.getElementById('graphWeeks');
const months = ['Sep', 'Oct', 'Nov', 'Dec', 'Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug'];
const levels = [0, 0, 0, 0, 1, 1, 2, 3, 4];

// Create month labels
const monthsRow = document.createElement('div');
monthsRow.style.cssText = 'display:flex;gap:3px;margin-bottom:4px;padding-left:0';
months.forEach(m => {
  const span = document.createElement('span');
  span.style.cssText = 'font-size:10px;color:#656d76;min-width:52px;display:inline-block';
  span.textContent = m;
  monthsRow.appendChild(span);
});

for (let w = 0; w < 52; w++) {
  const week = document.createElement('div');
  week.className = 'graph-week';
  for (let d = 0; d < 7; d++) {
    const cell = document.createElement('div');
    cell.className = 'graph-cell';
    // Simulate contribution pattern: more activity in recent weeks
    if (w > 40 || (w > 20 && Math.random() > 0.6)) {
      const level = levels[Math.floor(Math.random() * levels.length)];
      if (level > 0) cell.classList.add('l' + level);
    }
    week.appendChild(cell);
  }
  weeksContainer.appendChild(week);
}
